def cstr(s):
    return json.dumps(s, ensure_ascii=False)


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    out = os.path.join(here, "..", "src", "I18nData.inc")
    keys = list(T.keys())
    for k, v in T.items():
        assert len(v) == len(LANGS), (k, len(v))
    lines = [
        "// UVC Studio interface strings. Generated by tools/gen_i18n.py — edit that file instead.",
        "#pragma once",
        '#include "I18n.h"',
        "namespace gen {",
        "static const char* kKeys[] = {" + ",".join(cstr(k) for k in keys) + "};",
        f"static const int kKeyCount = {len(keys)};",
        f"static const int kLangCount = {len(LANGS)};",
        f"static const int kEnglish = {LANGS.index('en')};",
        "static const char* kLangOrder[] = {" + ",".join(cstr(l) for l in LANGS) + "};",
        f"struct LangTable {{ const char* code; const char* values[{len(keys)}]; }};",
        "static const LangTable kLangs[] = {",
    ]
    for i, lang in enumerate(LANGS):
        vals = ", ".join(cstr(T[k][i]) for k in keys)
        lines.append(f"  {{{cstr(lang)}, {{{vals}}}}},")
    lines += ["};", "}  // namespace gen", ""]
    with open(out, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    print(f"wrote {out}: {len(keys)} keys x {len(LANGS)} languages")


if __name__ == "__main__":
    main()
